  'pol.stat.mp': { en: `Frozen at the 2025 salary, without extras`, nl: `Bevroren op het loon van 2025, zonder extra's`, fr: `Gelé au salaire de 2025, sans les suppléments` },
  'polTitle.gov': { en: `Other public offices, gross pay`, nl: `Andere openbare ambten, brutoloon`, fr: `Autres fonctions publiques, rémunération brute` },
  'pol.president': { en: `President of the Republic`, nl: `President van de republiek`, fr: `Président de la République` },
  'polNote.pm': {
    en: `Taxed like a salary, with insurance and the extra 10% tax on officials. Their untaxed expense money (about 4 590 € a month, worked out from reported totals) is added to their take-home pay. The face sits at the salary an employee in your household would need to take home the same amount. The dot is their real pay before tax.`,
    nl: `Belast als loon, met bijdragen en de extra belasting van 10% voor ambtsdragers. Hun onbelast onkostengeld (ongeveer € 4.590 per maand, berekend uit gemelde totalen) komt bij hun nettoloon. Het gezichtje staat op het loon dat een werknemer met jouw gezin nodig heeft om hetzelfde netto over te houden. Het bolletje is hun echte loon vóór belasting.`,
    fr: `Imposé comme un salaire, avec cotisations et l'impôt supplémentaire de 10% des élus. Leur argent pour frais non imposé (environ 4 590 € par mois, calculé à partir de totaux publiés) s'ajoute à leur net. Le visage est placé au salaire qu'un salarié avec votre foyer devrait toucher pour garder le même net. Le point est leur vraie paie avant impôts.`,
  },
  'polNote.minister': {
    en: `Taxed like a salary, with insurance and the extra 10% tax on officials. The government also gives them untaxed expense money (about 1 824 € a month, worked out from one reported total), which is added to their take-home pay. The face sits at the salary an employee in your household would need to take home the same amount. The dot is their real pay before tax.`,
    nl: `Belast als loon, met bijdragen en de extra belasting van 10% voor ambtsdragers. De regering geeft hen ook onbelast onkostengeld (ongeveer € 1.824 per maand, berekend uit één gemeld totaal), dat bij hun nettoloon komt. Het gezichtje staat op het loon dat een werknemer met jouw gezin nodig heeft om hetzelfde netto over te houden. Het bolletje is hun echte loon vóór belasting.`,
    fr: `Imposé comme un salaire, avec cotisations et l'impôt supplémentaire de 10% des élus. Le gouvernement leur donne aussi de l'argent pour frais non imposé (environ 1 824 € par mois, calculé à partir d'un seul total publié), ajouté à leur net. Le visage est placé au salaire qu'un salarié avec votre foyer devrait toucher pour garder le même net. Le point est leur vraie paie avant impôts.`,
  },
  'polNote.mp': {
    en: `Taxed like a salary, with insurance and the extra 10% tax on officials. Their fixed untaxed expense money of 3 201 € (2 744 € for MPs from Bratislava) is added to their take-home pay. The budget for assistants and an office is not. The face sits at the salary an employee would need to take home the same amount.`,
    nl: `Belast als loon, met bijdragen en de extra belasting van 10% voor ambtsdragers. Hun vast onbelast onkostengeld van € 3.201 (€ 2.744 voor parlementsleden uit Bratislava) komt bij hun nettoloon. Het budget voor medewerkers en een kantoor niet. Het gezichtje staat op het loon dat een werknemer nodig heeft om hetzelfde netto over te houden.`,
    fr: `Imposé comme un salaire, avec cotisations et l'impôt supplémentaire de 10% des élus. Leur argent fixe pour frais non imposé de 3 201 € (2 744 € pour les députés de Bratislava) s'ajoute à leur net. Le budget pour les assistants et un bureau, non. Le visage est placé au salaire qu'un salarié devrait toucher pour garder le même net.`,
  },
  'polNote.president': {
    en: `4 times what MPs would earn without the freeze, taxed with insurance and the extra 10% tax. The 1 327.76 € a month of untaxed expense money is added to their take-home pay. The face sits at the salary an employee would need to take home the same amount.`,
    nl: `4 keer wat parlementsleden zonder bevriezing zouden verdienen, belast met bijdragen en de extra belasting van 10%. Het onbelaste onkostengeld van € 1.327,76 per maand komt bij het nettoloon. Het gezichtje staat op het loon dat een werknemer nodig heeft om hetzelfde netto over te houden.`,
    fr: `4 fois ce que gagneraient les députés sans gel, imposé avec cotisations et l'impôt supplémentaire de 10%. Les 1 327,76 € par mois d'argent pour frais non imposé s'ajoutent au net. Le visage est placé au salaire qu'un salarié devrait toucher pour garder le même net.`,
  },
  'polTipNote.president': {
    en: `19 440 € a month in 2026 (4 × 4 860 €), plus 1 327.76 € of untaxed expense money: about 20 768 € in total, as reported in March 2026. The President said he would give the raise away.`,
    nl: `€ 19.440 per maand in 2026 (4 × € 4.860), plus € 1.327,76 onbelast onkostengeld: ongeveer € 20.768 in totaal, zoals gemeld in maart 2026. De president zei dat hij de verhoging zou wegschenken.`,
    fr: `19 440 € par mois en 2026 (4 × 4 860 €), plus 1 327,76 € d'argent pour frais non imposé : environ 20 768 € au total, selon les chiffres publiés en mars 2026. Le président a dit qu'il donnerait la hausse.`,
  },
  polNote: {
    en: links => `Point at a name to see details, click it to zoom in. Pay is for the year before tax; the chart shows it per month (÷ 12). Officials sit where an employee would take home the same amount, their untaxed expense money included. Source: ${links}.`,
    nl: links => `Wijs een naam aan voor details, klik om in te zoomen. Het loon is voor het jaar vóór belasting; de grafiek toont het per maand (÷ 12). Ambtsdragers staan waar een werknemer hetzelfde netto zou overhouden, hun onbelast onkostengeld inbegrepen. Bron: ${links}.`,
    fr: links => `Pointez un nom pour voir les détails, cliquez pour zoomer. La paie est celle de l'année avant impôts ; le graphique la montre par mois (÷ 12). Les élus sont placés là où un salarié garderait le même net, argent pour frais non imposé compris. Source : ${links}.`,
  },
  'src.pol.pm': { en: `Noviny.sk: officials' pay 2026`, nl: `Noviny.sk: lonen ambtsdragers 2026`, fr: `Noviny.sk : rémunérations des élus 2026` },
